package org.springframework.samples.petclinic.blackbox;

import static org.springframework.samples.petclinic.blackbox.support.BlackBoxSupport.BASE_URL;
import static org.springframework.samples.petclinic.blackbox.support.BlackBoxSupport.executeSqlTemplate;
import static org.springframework.samples.petclinic.blackbox.support.BlackBoxSupport.testId;
import static org.springframework.samples.petclinic.blackbox.support.BlackBoxSupport.testSeq;
import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.notNullValue;

import java.util.Map;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import io.restassured.http.ContentType;

/**
 * Black-Box API Integration Test (template-rendered v2)
 *
 * @target-controller AuthController (src/main/java/org/springframework/samples/petclinic/security/AuthController.java)
 * @target-api POST /api/auth/login
 *
 * AuthController.login: JWT 토큰 기반 로그인 엔드포인트
 * 사용자명/비밀번호를 입력받아 JWT 토큰 발급
 * 하드코딩된 사용자: admin/password, user/password
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class AuthLoginBlackBoxTest {

    private Map<String, String> seed(TestInfo info) {
        return Map.of(
                "USERNAME_ADMIN", "admin",
                "PASSWORD_CORRECT", "password",
                "PASSWORD_WRONG", "wrongpass",
                "USERNAME_INVALID", "nonexistent");
    }

    private void arrange(Map<String, String> p) {
        executeSqlTemplate("sql/auth-login-teardown.sql", p);
        executeSqlTemplate("sql/auth-login-setup.sql", p);
    }

    @Test
    void NTC_login_success_admin(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Content-Type", "application/json")
                    .contentType(ContentType.JSON)
                    .body("\"{\\\"username\\\":\\\"" + p.get("USERNAME_ADMIN") + "\\\",\\\"password\\\":\\\"" + p.get("PASSWORD_CORRECT") + "\\\"}\"")
            .when()
                    .post("/api/auth/login")
            .then()
                    .statusCode(200)
                    .body("token", notNullValue())
                    .body("type", equalTo("Bearer"))
                    .body("username", equalTo("admin"))
                    .body("expiresIn", equalTo("86400"));
        } finally {
            executeSqlTemplate("sql/auth-login-teardown.sql", p);
        }
    }

    @Test
    void NTC_login_success_user(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Content-Type", "application/json")
                    .contentType(ContentType.JSON)
                    .body("\"{\\\"username\\\":\\\"user\\\",\\\"password\\\":\\\"" + p.get("PASSWORD_CORRECT") + "\\\"}\"")
            .when()
                    .post("/api/auth/login")
            .then()
                    .statusCode(200)
                    .body("token", notNullValue())
                    .body("type", equalTo("Bearer"))
                    .body("username", equalTo("user"));
        } finally {
            executeSqlTemplate("sql/auth-login-teardown.sql", p);
        }
    }

    @Test
    void ATC_login_invalid_password(TestInfo info) {
        Map<String, String> p = seed(info);
        arrange(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Content-Type", "application/json")
                    .contentType(ContentType.JSON)
                    .body("\"{\\\"username\\\":\\\"" + p.get("USERNAME_ADMIN") + "\\\",\\\"password\\\":\\\"" + p.get("PASSWORD_WRONG") + "\\\"}\"")
            .when()

